#include <unity.h>
#include "mesh_route.h"
#include <string.h>
static const uint8_t A[8]={1,0,0,0,0,0,0,1}, B[8]={2,0,0,0,0,0,0,2}, C[8]={3,0,0,0,0,0,0,3}, D[8]={4,0,0,0,0,0,0,4};
void test_route_path_marks_once_and_returns_next_hop(){ml::RoutePath p;memcpy(p.sender,A,8);memcpy(p.receiver,D,8);p.nodeCount=3;memcpy(p.nodes[0],A,8);memcpy(p.nodes[1],B,8);memcpy(p.nodes[2],D,8);TEST_ASSERT_TRUE(p.isValid());TEST_ASSERT_TRUE(p.markVisited(A));TEST_ASSERT_FALSE(p.markVisited(A));uint8_t n[8]={0};TEST_ASSERT_TRUE(p.nextHop(A,n));TEST_ASSERT_EQUAL_MEMORY(B,n,8);TEST_ASSERT_FALSE(p.nextHop(B,n));TEST_ASSERT_TRUE(p.markVisited(B));TEST_ASSERT_TRUE(p.nextHop(B,n));TEST_ASSERT_EQUAL_MEMORY(D,n,8);}
void test_route_rejects_duplicate_nodes(){ml::RoutePath p;memcpy(p.sender,A,8);memcpy(p.receiver,D,8);p.nodeCount=3;memcpy(p.nodes[0],A,8);memcpy(p.nodes[1],B,8);memcpy(p.nodes[2],B,8);TEST_ASSERT_FALSE(p.isValid());}
void test_route_table_selects_lowest_combined_cost(){ml::RouteTable t;t.upsertLink(A,B,8,0);t.upsertLink(B,D,8,0);t.upsertLink(A,C,4,100);t.upsertLink(C,D,4,100);ml::RoutePath current,result;TEST_ASSERT_TRUE(t.calculate(A,D,current,result));TEST_ASSERT_EQUAL_UINT8(3,result.nodeCount);TEST_ASSERT_EQUAL_MEMORY(B,result.nodes[1],8);TEST_ASSERT_TRUE(result.hasVisited(A));}
void test_reroute_avoids_visited_repeater_and_preserves_history(){ml::RouteTable t;t.upsertLink(A,B,5,0);t.upsertLink(B,D,5,0);t.upsertLink(A,C,8,0);t.upsertLink(C,D,8,0);ml::RoutePath current,first,alternate;TEST_ASSERT_TRUE(t.calculate(A,D,current,first));TEST_ASSERT_TRUE(first.markVisited(B));TEST_ASSERT_TRUE(t.calculate(A,D,first,alternate));TEST_ASSERT_EQUAL_MEMORY(C,alternate.nodes[1],8);TEST_ASSERT_TRUE(alternate.hasVisited(A));TEST_ASSERT_TRUE(alternate.hasVisited(B));TEST_ASSERT_FALSE(alternate.markVisited(B));}
void test_health_quorum_and_maintenance(){ml::NodeHealthMonitor h;TEST_ASSERT_TRUE(h.reportFailure(D,B,100));TEST_ASSERT_EQUAL((int)ml::NodeHealth::Unstable,(int)h.state(D));TEST_ASSERT_TRUE(h.reportFailure(D,B,101));TEST_ASSERT_EQUAL((int)ml::NodeHealth::Unstable,(int)h.state(D));TEST_ASSERT_TRUE(h.reportFailure(D,C,102));TEST_ASSERT_EQUAL((int)ml::NodeHealth::SuspectedDown,(int)h.state(D));TEST_ASSERT_TRUE(h.setMaintenance(D,true));TEST_ASSERT_FALSE(h.reportFailure(D,B,103));TEST_ASSERT_EQUAL((int)ml::NodeHealth::Maintenance,(int)h.state(D));}
void test_health_recovery_quorum(){ml::NodeHealthMonitor h;h.reportFailure(D,B,1);h.reportFailure(D,C,2);TEST_ASSERT_TRUE(h.reportSuccess(D,B,3));TEST_ASSERT_EQUAL((int)ml::NodeHealth::Recovering,(int)h.state(D));TEST_ASSERT_TRUE(h.reportSuccess(D,C,4));TEST_ASSERT_EQUAL((int)ml::NodeHealth::Online,(int)h.state(D));}
void test_retry_twice_then_cooldown(){ml::LinkRetryPolicy r;TEST_ASSERT_TRUE(r.recordFailure(A,B,100));TEST_ASSERT_TRUE(r.recordFailure(A,B,200));TEST_ASSERT_FALSE(r.recordFailure(A,B,300));TEST_ASSERT_TRUE(r.isTemporarilyUnavailable(A,B,301));r.expire(100+ml::ROUTE_UNAVAILABLE_TTL_MS);TEST_ASSERT_FALSE(r.isTemporarilyUnavailable(A,B,100+ml::ROUTE_UNAVAILABLE_TTL_MS));TEST_ASSERT_TRUE(r.recordFailure(A,B,ml::ROUTE_UNAVAILABLE_TTL_MS+101));}
void test_success_clears_failure_history(){ml::LinkRetryPolicy r;TEST_ASSERT_TRUE(r.recordFailure(A,B,10));r.markSuccess(A,B);TEST_ASSERT_TRUE(r.recordFailure(A,B,11));}
int main(){UNITY_BEGIN();RUN_TEST(test_route_path_marks_once_and_returns_next_hop);RUN_TEST(test_route_rejects_duplicate_nodes);RUN_TEST(test_route_table_selects_lowest_combined_cost);RUN_TEST(test_reroute_avoids_visited_repeater_and_preserves_history);RUN_TEST(test_health_quorum_and_maintenance);RUN_TEST(test_health_recovery_quorum);RUN_TEST(test_retry_twice_then_cooldown);RUN_TEST(test_success_clears_failure_history);return UNITY_END();}
